import {Icon, IndexPath} from '@ui-kitten/components';
import React from 'react';
import {TouchableOpacity, View} from 'react-native';
import DropdownListCM from '../../../../components/DropDownList';
import {useTranslation} from 'react-i18next';
import {Font} from '../../../../../constants';
import TextCM from '../../../../components/Text';
import InputDate from './InputDate';
import {listPayment, listRequestStatus, listStatusReceipt} from './helper';
import {useReceiptZustandStore} from '../../store/myReceiptZustandStore';
import Toast from 'react-native-toast-message';
type Props = {
  onClose: () => void;
  handleSubmitFilter?: () => void;
};
const ModalFilter = ({onClose, handleSubmitFilter}: Props) => {
  const {t} = useTranslation();
  const {valueFilterSearch, setValueFilterSearch, listTypeReceipt} =
    useReceiptZustandStore();

  const onChangeStartDate = (value: string | null) => {
    const newStart = value ? new Date(value) : undefined;
    const {endDate} = valueFilterSearch.rangeDay ?? {};
    if (endDate && newStart && newStart > endDate) {
      Toast.show({
        type: 'error',
        text1: t('CM.noti'),
        text2: 'Ngày bắt đầu không được lớn hơn ngày kết thúc.',
      });
      return;
    }

    setValueFilterSearch({
      ...valueFilterSearch,
      rangeDay: {
        ...valueFilterSearch.rangeDay,
        startDate: newStart,
      },
    });
  };
  const onChangeEndDate = (value: string | null) => {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const newEnd = value ? new Date(value) : undefined;
    if (newEnd && newEnd > today) {
      Toast.show({
        type: 'error',
        text1: t('CM.noti'),
        text2: 'Ngày kết thúc không được lớn hơn ngày hôm nay.',
      });
      return;
    }
    const {startDate} = valueFilterSearch.rangeDay ?? {};
    if (startDate && newEnd && newEnd < startDate) {
      Toast.show({
        type: 'error',
        text1: t('CM.not'),
        text2: 'Ngày kết thúc không được nhỏ hơn ngày bắt đầu.',
      });
      return;
    }
    setValueFilterSearch({
      ...valueFilterSearch,
      rangeDay: {...valueFilterSearch.rangeDay, endDate: newEnd},
    });
  };

  const handleClear = () => {
    setValueFilterSearch({});
  };

  return (
    <View style={{backgroundColor: '#fff'}}>
      <View style={{marginVertical: 4}}>
        <TextCM
          style={{
            marginVertical: 8,
            fontFamily: Font.InterMedium500,
            fontSize: 14,
          }}>
          Loại biên lai
        </TextCM>
        <DropdownListCM
          onSelect={(item: IndexPath[]) => {
            setValueFilterSearch({...valueFilterSearch, type: item});
          }}
          valueSelect={valueFilterSearch.type}
          placeholder={'Chọn loại biên lai'}
          multiple={true}
          listData={listTypeReceipt}
        />
      </View>
      <View style={{marginVertical: 4}}>
        <TextCM
          style={{
            marginVertical: 8,
            fontFamily: Font.InterMedium500,
            fontSize: 14,
          }}>
          Hình thức nộp tiền
        </TextCM>
        <DropdownListCM
          onSelect={(item: IndexPath[]) => {
            setValueFilterSearch({...valueFilterSearch, paymentMethod: item});
          }}
          valueSelect={valueFilterSearch.paymentMethod}
          placeholder={'Chọn hình thức nộp tiền'}
          multiple={true}
          listData={listPayment}
        />
      </View>
      <View style={{marginVertical: 4}}>
        <TextCM
          style={{
            marginVertical: 8,
            fontFamily: Font.InterMedium500,
            fontSize: 14,
          }}>
          Trạng thái biên lai
        </TextCM>
        <DropdownListCM
          onSelect={(item: IndexPath[]) => {
            setValueFilterSearch({...valueFilterSearch, status: item});
          }}
          valueSelect={valueFilterSearch.status}
          placeholder={'Chọn trạng thái'}
          multiple={true}
          listData={listStatusReceipt}
        />
      </View>

      <View style={{marginVertical: 4}}>
        <TextCM
          style={{
            marginVertical: 8,
            fontFamily: Font.InterMedium500,
            fontSize: 14,
          }}>
          Trạng thái nộp quỹ
        </TextCM>
        <DropdownListCM
          onSelect={(item: IndexPath[]) => {
            setValueFilterSearch({...valueFilterSearch, requestStatus: item});
          }}
          valueSelect={valueFilterSearch.requestStatus}
          placeholder={'Chọn trạng thái nộp quỹ'}
          multiple={true}
          listData={listRequestStatus}
        />
      </View>
      <View style={{marginVertical: 4, marginBottom: 12}}>
        <TextCM
          style={{
            marginVertical: 8,
            fontFamily: Font.InterMedium500,
            fontSize: 14,
          }}>
          Lọc theo ngày tạo
        </TextCM>
        <View
          style={{
            flexDirection: 'row',
            justifyContent: 'space-between',
            alignItems: 'center',
            marginTop: 10,
            columnGap: 8,
          }}>
          <InputDate
            containerStyle={{flex: 1}}
            value={valueFilterSearch?.rangeDay?.startDate || null}
            onChangeDate={value => {
              onChangeStartDate(value);
            }}
            disabled={false}
          />
          <Icon name="arrow-forward-outline" width={20} height={20} />
          <InputDate
            containerStyle={{flex: 1}}
            value={valueFilterSearch?.rangeDay?.endDate || null}
            onChangeDate={value => {
              onChangeEndDate(value);
            }}
            disabled={false}
          />
        </View>
      </View>
      <View
        style={{
          flexDirection: 'row',
          justifyContent: 'space-evenly',
          alignItems: 'center',
          gap: 16,
        }}>
        <TouchableOpacity
          onPress={handleClear}
          style={{
            flex: 1,
            padding: 12,
            backgroundColor: '#FBEFEA',
            borderRadius: 8,
          }}>
          <TextCM style={{color: '#C83A1B', textAlign: 'center'}}>
            {t('DB.set-default')}
          </TextCM>
        </TouchableOpacity>
        <TouchableOpacity
          onPress={() => handleSubmitFilter?.()}
          style={{
            flex: 1,
            padding: 12,
            backgroundColor: '#C83A1B',
            borderRadius: 8,
          }}>
          <TextCM style={{color: '#fff', textAlign: 'center'}}>Lọc</TextCM>
        </TouchableOpacity>
      </View>
    </View>
  );
};

export default ModalFilter;
