import {TabBar, TabView} from 'react-native-tab-view';
import {Color, Font} from '../../../../../constants';
import {useState} from 'react';
import {useTranslation} from 'react-i18next';
import {StyleSheet, useWindowDimensions} from 'react-native';
import ListReceipt from './conponent/list-receipt';
import {useReceiptZustandStore} from '../../store/myReceiptZustandStore';
import {
  REQUEST_FLOW,
  TYPE_REQUEST_FLOW,
} from '../../../../../model/type/status';
import TextCM from '../../../../components/Text';
type Route = {
  key: TYPE_REQUEST_FLOW;
  title: string;
};
const RenderTabView = () => {
  const [index, setIndex] = useState(0);
  const {t} = useTranslation();
  const layout = useWindowDimensions();
  const {setCurrentStatusRequestReceipt} = useReceiptZustandStore();
  const routes: Route[] = REQUEST_FLOW.map(item => {
    return {
      key: item,
      title: t(`BLDT.${item}`),
    };
  });
  const renderTabBar = (props: any) => (
    <TabBar
      {...props}
      onTabPress={routes =>
        setCurrentStatusRequestReceipt(routes?.route?.key as TYPE_REQUEST_FLOW)
      }
      indicatorStyle={{backgroundColor: Color.BgPrimary}}
      style={{backgroundColor: Color.White}}
      scrollEnabled
      activeColor="#C83A1B"
      renderLabel={({route, focused}) => (
        <TextCM
          style={[
            styles.labelTabbar,
            {color: focused ? '#C83A1B' : '#00204DB2'},
          ]}>
          {t(route.title || '')}
        </TextCM>
      )}
      // tabStyle={{width: 130}}
    />
  );
  const renderScene = ({
    route,
  }: {
    route: {
      key: TYPE_REQUEST_FLOW;
    };
  }) => {
    return <ListReceipt flowStatus={route.key} />;
  };
  return (
    <>
      <TabView
        lazy
        style={{backgroundColor: '#f9fafe'}}
        sceneContainerStyle={styles.sceneContainer}
        renderTabBar={renderTabBar}
        navigationState={{index, routes}}
        renderScene={renderScene}
        onIndexChange={setIndex}
        initialLayout={{width: layout.width}}
        swipeEnabled={false}
      />
    </>
  );
};
export default RenderTabView;

const styles = StyleSheet.create({
  labelTabbar: {
    color: '#00204DB2',
    fontFamily: Font.InterRegular400,
    fontSize: 14,
    textAlign: 'center',
    width: 'auto',
  },
  sceneContainer: {
    paddingHorizontal: 16,
    paddingVertical: 10,
  },
});
